use crate::model::{Document,Node,NodeKind}; use std::collections::BTreeMap;
pub fn parse(input:&str)->Document { let mut root=Node::default(); let mut stack=vec![0usize]; let mut nodes:Vec<Node>=vec![root.clone()]; let mut text=String::new();
 for part in input.split('<') { if let Some((tag,rest))=part.split_once('>') { if !text.trim().is_empty(){nodes[*stack.last().unwrap()].children.push(Node{kind:NodeKind::Text(text.trim().into()),children:vec![]})}; text.clear(); let t=tag.trim(); if t.starts_with('/') {if stack.len()>1{stack.pop();}} else if !t.is_empty()&&!t.starts_with('!') { let name=t.split_whitespace().next().unwrap().trim_end_matches('/').to_ascii_lowercase(); let n=Node{kind:NodeKind::Element{name,attrs:BTreeMap::new()},children:vec![]}; nodes.push(n); let i=nodes.len()-1; nodes[*stack.last().unwrap()].children.push(nodes[i].clone()); if !t.ends_with('/') {stack.push(i);} } text.push_str(rest); } else {text.push_str(part)} }
 if !text.trim().is_empty(){nodes[0].children.push(Node{kind:NodeKind::Text(text.trim().into()),children:vec![]})}; root=nodes[0].clone(); Document{root} }
#[cfg(test)] mod tests { use super::*; #[test] fn parses(){assert_eq!(crate::dom::body_text(&parse("<p>Hello</p>")),"Hello");} }
